WITH cleaned AS (SELECT *, LOWER(txn_type) AS txn_type_lower FROM transactions WHERE merchant IS NOT NULL) SELECT *, NTILE(5) OVER (ORDER BY amount DESC, id) AS amount_bucket, AVG(amount) OVER (PARTITION BY txn_type ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS amount_avg_6, LAG(amount, 1) OVER (PARTITION BY merchant ORDER BY amount, id) AS prev_amount, LEAD(amount, 1) OVER (ORDER BY amount, id) AS next_amount, CUME_DIST() OVER (PARTITION BY merchant, txn_type ORDER BY amount DESC NULLS FIRST) AS amount_cume_dist FROM cleaned;
